const revealObserver=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}})},{threshold:.12});document.querySelectorAll('.reveal').forEach((el)=>revealObserver.observe(el));
const buttons=document.querySelectorAll('.filters button');const cards=document.querySelectorAll('.designer-card');buttons.forEach((button)=>button.addEventListener('click',()=>{buttons.forEach((b)=>b.classList.remove('active'));button.classList.add('active');const filter=button.dataset.filter;cards.forEach((card)=>{card.classList.toggle('hidden',filter!=='all'&&card.dataset.era!==filter)})}));
const line=document.querySelector('.timeline-line span');const timeline=document.querySelector('.timeline');function updateTimeline(){const rect=timeline.getBoundingClientRect();const progress=Math.max(0,Math.min(1,(innerHeight*.7-rect.top)/rect.height));line.style.height=`${progress*100}%`}addEventListener('scroll',updateTimeline,{passive:true});updateTimeline();
