const authorModal=document.querySelector('#author-modal');const authorVisual=authorModal.querySelector('.author-modal-visual');const authorImage=authorVisual.querySelector('img');const authorMonogram=authorVisual.querySelector('span');const previewMeta=authorVisual.querySelector('.work-preview-meta');function openAuthor(key){const data=authorData[key];if(!data)return;const featuredIndex=displayedWorkIndex[key];const featuredWork=Number.isInteger(featuredIndex)?data.works[featuredIndex]:null;authorModal.querySelector('h2').textContent=data.name;authorModal.querySelector('.author-modal-description').textContent=data.description;authorModal.querySelector('.author-modal-source').href=data.source;authorModal.querySelector('.author-modal-works').innerHTML=data.works.map((work,index)=>`<li${index===featuredIndex?' class="featured"':''}><i>${String(index+1).padStart(2,'0')}</i><b>${work[0]}</b><em>${work[1]}</em></li>`).join('');authorVisual.classList.toggle('no-image',!data.image);authorVisual.style.backgroundImage=data.image?`url("${data.image}")`:'none';authorVisual.setAttribute('role',data.image?'img':'group');authorVisual.setAttribute('aria-label',data.alt||data.name);authorImage.src='';authorImage.alt='';authorMonogram.textContent=data.monogram||'';previewMeta.hidden=!featuredWork;previewMeta.querySelector('b').textContent=featuredWork?featuredWork[0]:'';previewMeta.querySelector('small').textContent=featuredWork?featuredWork[1]:'';authorModal.showModal()}document.querySelectorAll('[data-author]').forEach((card)=>{card.addEventListener('click',()=>openAuthor(card.dataset.author));card.addEventListener('keydown',(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openAuthor(card.dataset.author)}})});authorModal.querySelector('.author-modal-close').addEventListener('click',()=>authorModal.close());authorModal.addEventListener('click',(event)=>{if(event.target===authorModal)authorModal.close()});
